\begin{tikzpicture}[x=5mm,y=5mm]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\foreach \x in {0,...,6}{
  \foreach \y in {0,...,6}{
    \pgfmathtruncatemacro{\layerparity}{mod(max(\x,\y),2)}
    \ifnum\layerparity=0
      \fill[black] (\x,\y) circle[radius=0.9mm];
    \else
      \draw[black,line width=0.4pt,fill=white] (\x,\y) circle[radius=1.05mm];
    \fi
  }
}
\end{tikzpicture}

